The submission:
```python
def is_balanced(s: str) -> bool:
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = {'(', '[', '{'}
    closing = {')', ']', '}'}

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in closing:
            if not stack:
                return False
            top = stack.pop()
            if matching[char] != top:
                return False

    return len(stack) == 0
```

