def letter_stats(s: str) -> dict[str, int]:
    vowels = set('aeiouAEIOU')
    consonants = set('bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ')

    counts = {'vowels': 0, 'consonants': 0, 'digits': 0, 'other': 0}

    for char in s:
        if char.isspace():
            continue
        if char in vowels:
            counts['vowels'] += 1
        elif char in consonants:
            counts['consonants'] += 1
        elif char.isdigit():
            counts['digits'] += 1
        else:
